-- View: main.canonical_us_patient_master_v2
-- Pulled: 2026-04-21 Part B Phase 2 recon

CREATE VIEW canonical_us_patient_master_v2 AS WITH exam_agg AS (SELECT research_id, CAST('t' AS BOOLEAN) AS has_any_us, count_star() AS n_us_exams, min(exam_date) AS first_us_date, max(exam_date) AS last_us_date, bool_or(is_preop_exam) AS preop_us_available_flag, max(worst_tirads_category_this_exam) AS max_tirads_category_ever, max(worst_tirads_points_this_exam) AS max_tirads_points_ever, sum(n_nodules_on_exam) AS n_nodules_total_across_exams, bool_or(bilateral_flag) AS bilateral_disease_flag_ever, (sum(CASE  WHEN ((n_nodules_on_exam >= 2)) THEN (1) ELSE 0 END) > 0) AS multifocal_flag_ever, bool_or(has_us_ln_findings) AS has_us_ln_findings_ever, bool_or(has_gland_findings) AS has_gland_findings_ever, (sum(COALESCE(n_abnormal_us_ln_on_exam, 0)) > 0) AS any_suspicious_us_ln_ever, min(CASE  WHEN (((n_abnormal_us_ln_on_exam IS NOT NULL) AND (n_abnormal_us_ln_on_exam > 0))) THEN (exam_date) ELSE NULL END) AS first_abnormal_us_ln_date, bool_or(any_nlp_backfill_pending_on_exam) AS any_nlp_backfill_pending_for_patient FROM main.canonical_us_exam_master_v2 GROUP BY 1), nodule_first_last AS (SELECT e.research_id, any_value(e.worst_tirads_category_this_exam ORDER BY e.exam_date) FILTER (WHERE (e.exam_rank_for_patient = 1)) AS tirads_category_at_first_exam, any_value(e.worst_tirads_category_this_exam ORDER BY e.exam_date DESC) FILTER (WHERE (CAST(e.is_preop_exam AS BOOLEAN) IS NOT DISTINCT FROM CAST('t' AS BOOLEAN))) AS tirads_category_at_last_preop_exam, min(CASE  WHEN ((upper(e.worst_tirads_category_this_exam) IN ('TR4', 'TR5'))) THEN (e.exam_date) ELSE NULL END) AS first_high_risk_tirads_date FROM main.canonical_us_exam_master_v2 AS e GROUP BY 1), nodule_agg AS (SELECT research_id, max(COALESCE("nullif"(greatest(COALESCE(length_mm, 0), COALESCE(width_mm, 0), COALESCE(height_mm, 0)), 0), (size_cm_max * 10.0))) AS max_nodule_size_mm, count_star() AS n_nodule_records FROM main.canonical_us_nodule_v2 GROUP BY 1)SELECT e.research_id, e.has_any_us, e.n_us_exams, e.first_us_date, e.last_us_date, e.preop_us_available_flag, e.max_tirads_category_ever, e.max_tirads_points_ever, nfl.tirads_category_at_first_exam, nfl.tirads_category_at_last_preop_exam, e.n_nodules_total_across_exams, e.bilateral_disease_flag_ever, e.multifocal_flag_ever, nfl.first_high_risk_tirads_date, e.has_us_ln_findings_ever, e.any_suspicious_us_ln_ever, e.first_abnormal_us_ln_date, e.has_gland_findings_ever, e.any_nlp_backfill_pending_for_patient, bf.imaging_laterality_rollup_v2, bf.pathology_vs_imaging_laterality_concordant_v2, bf.tumor_pathology_laterality_v2, bf.any_fna_recommended_report_ever, bf.any_fna_recommended_report_source, bf.tirads_worst_rank_ever, bf.tirads_worst_rank_source, na.max_nodule_size_mm, na.n_nodule_records FROM exam_agg AS e LEFT JOIN nodule_first_last AS nfl USING (research_id) LEFT JOIN main.cupm_v2_canonical_backfill_v1 AS bf USING (research_id) LEFT JOIN nodule_agg AS na USING (research_id);
